function Page_PopUpGiftLevelView:CountDownTime()
    if  self.cs_countdown == nil then
        self.cs_countdown = cs_coroutine.start(function()
            while  self.data and self.data:IsActive() do
                local timestr = string.format(CommonHelper:GetTempStr_Default(self.data.contentTable[8]),self:GetDataTimeString())
                CommonHelper:SetText("###ContentText8",self.gameObject,timestr)
                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
            end
            UINotify:Get():SendNotification(UINotifyEvent.PopUpGiftView_Refresh)
        end)
    end
end

function Page_PopUpGiftLevelView:OnClose()
